import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        InputStreamReader isr = new InputStreamReader(System.in);
        BufferedReader br = new BufferedReader(isr);
        PrintWriter pw = new PrintWriter(System.out);
        Solver solver = new Solver();
        solver.solve(br, pw);
        pw.close();
    }

    static class Solver {
        public void solve(BufferedReader br, PrintWriter out) throws IOException {
            int n = Integer.parseInt(br.readLine());
            String s = br.readLine();
            int winCount = 0, maxSegmentLength = 0;
            int left = 0, right = 0;
            while (s.contains("__")) s = s.replace("__", "_");
            n = s.length();

            if (s.charAt(left) == '(') {
                while (right < n && s.charAt(right) != ')') right++;
                if (right < n && s.charAt(right) == ')') {
                    String inside = s.substring(left + 1, right);
                    if (!inside.contains("_") && inside.length() > 0)
                        winCount++;
                    else {
                        String[] tokens = inside.split("_");
                        winCount += tokens.length;
                    }
                    left = right + 1;
                }
            }

            for (int index = 0; index < n; index++) {
                if (s.charAt(index) == '(') {
                    int closeIdx = index;
                    while (closeIdx < n && s.charAt(closeIdx) != ')') closeIdx++;
                    if (closeIdx < n && s.charAt(closeIdx) == ')') {
                        String inside = s.substring(index + 1, closeIdx);
                        if (!inside.contains("_") && inside.length() > 0)
                            winCount++;
                        else {
                            String[] tokens = inside.split("_");
                            winCount += tokens.length;
                        }
                        index = closeIdx;
                    }
                }
            }

            while (s.contains("(") || s.contains(")")) {
                s = s.replaceAll("\\([^\\(]*\\)", "_");
            }

            String[] segments = s.split("_");
            for (String segment : segments) {
                if (segment.length() > maxSegmentLength)
                    maxSegmentLength = segment.length();
            }

            out.println(maxSegmentLength + " " + winCount);
        }
    }
}
